
.readout {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 18px 16px 16px;
}

.readout-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.readout-age {
  display: flex;
  align-items: baseline;
  gap: 5px;
}

.readout-age-num {
  font-size: 30px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.03em;
  color: var(--c-text);
  font-variant-numeric: tabular-nums;
}

.readout-age-unit {
  font-size: 14px;
  color: var(--c-text-muted);
}

.readout-age-month {
  margin-left: 6px;
  font-size: 13px;
  color: var(--c-text-faint);
  font-variant-numeric: tabular-nums;
}

.readout-phase {
  padding: 3px 10px;
  border-radius: 999px;
  background: var(--c-accent-soft);
  color: var(--c-accent-hover);
  font-size: 12px;
  font-weight: 500;
}

.readout-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: var(--c-text-muted);
  font-variant-numeric: tabular-nums;
}

.readout-sep {
  color: var(--c-border-strong);
}

.readout-span {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 2px;
  padding: 8px 12px;
  border: 1px solid var(--c-border);
  border-radius: var(--r-sm);
  background: var(--c-surface-sunken);
}

.readout-span-label {
  flex: none;
  font-size: 12.5px;
  color: var(--c-text-muted);
}

.readout-range {
  flex: 1;
  min-width: 0;
  height: 4px;
  appearance: none;
  border-radius: 999px;
  background: var(--c-border-strong);
  outline: none;
  cursor: pointer;
}

.readout-range::-webkit-slider-thumb {
  appearance: none;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--c-accent);
  border: 2px solid var(--c-surface);
  box-shadow: var(--shadow-hair);
}

.readout-range::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--c-accent);
  border: 2px solid var(--c-surface);
}

.readout-span-value {
  flex: none;
  min-width: 52px;
  text-align: right;
  font-size: 13px;
  font-weight: 500;
  color: var(--c-text);
  font-variant-numeric: tabular-nums;
}

.btn-quiet {
  flex: none;
  padding: 5px 12px;
  border: 1px solid var(--c-border-strong);
  border-radius: var(--r-sm);
  background: var(--c-surface);
  color: var(--c-text-body);
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
}

.btn-quiet:hover {
  background: var(--c-surface-hover);
  border-color: var(--c-text-faint);
  color: var(--c-text);
}
