
.opening {
  display: flex;
  flex-direction: column;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: var(--r-md);
  overflow: hidden;
  animation: cl-enter 0.5s var(--ease-out) both;
}

.opening-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 20px 18px 18px;
}

.opening-title {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.015em;
  color: var(--c-text);
}

.opening-sub {
  margin-top: 2px;
  font-size: 12.5px;
  color: var(--c-text-muted);
}

.opening-tabs {
  display: flex;
  gap: 2px;
  margin: 0 16px;
  padding: 3px;
  border-radius: var(--r-sm);
  background: var(--c-bg-alt);
}

.opening-tab {
  flex: 1;
  padding: 6px 0;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--c-text-muted);
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
}

.opening-tab:hover {
  color: var(--c-text);
}

.opening-tab.is-active {
  background: var(--c-surface);
  color: var(--c-text);
  box-shadow: var(--shadow-hair);
}

.opening-body {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 16px;
}

.tpl {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 14px 15px;
  border: 1px solid var(--c-border);
  border-radius: var(--r-sm);
  background: var(--c-surface);
  text-align: left;
  cursor: pointer;
  animation: cl-enter 0.42s var(--ease-out) both;
}

.tpl:nth-child(2) {
  animation-delay: 50ms;
}

.tpl:nth-child(3) {
  animation-delay: 100ms;
}

.tpl:hover {
  background: var(--c-surface-sunken);
  border-color: var(--c-border-strong);
}

.tpl-index {
  font-size: 11px;
  color: var(--c-accent);
  letter-spacing: 0.2em;
}

.tpl-title {
  font-size: 14.5px;
  font-weight: 500;
  color: var(--c-text);
}

.tpl-meta {
  font-size: 12px;
  color: var(--c-text-faint);
}

.tpl-desc {
  margin-top: 3px;
  font-family: var(--f-serif);
  font-size: 13.5px;
  line-height: 1.7;
  color: var(--c-text-body);
}

.tpl-cast {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 6px;
}

.tpl-person {
  padding: 2px 9px;
  border-radius: 999px;
  background: var(--c-bg-alt);
  font-size: 11px;
  color: var(--c-text-muted);
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  font-size: 12px;
  color: var(--c-text-muted);
}

.field-area,
.field-input {
  width: 100%;
  padding: 9px 11px;
  border: 1px solid var(--c-border-strong);
  border-radius: var(--r-sm);
  background: var(--c-surface);
  color: var(--c-text);
  font-size: 13.5px;
  line-height: 1.6;
  outline: none;
  resize: vertical;
}

.field-area::placeholder {
  color: var(--c-text-faint);
}

.field-area:focus,
.field-input:focus {
  border-color: var(--c-accent);
  box-shadow: 0 0 0 3px var(--c-accent-soft);
}

.field-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.sex-row {
  display: flex;
  gap: 8px;
}

.sex {
  flex: 1;
  padding: 8px 0;
  border: 1px solid var(--c-border-strong);
  border-radius: var(--r-sm);
  background: var(--c-surface);
  color: var(--c-text-body);
  font-size: 13.5px;
  cursor: pointer;
}

.sex:hover {
  background: var(--c-surface-sunken);
}

.sex.is-active {
  border-color: var(--c-accent);
  background: var(--c-accent-soft);
  color: var(--c-accent-hover);
  font-weight: 500;
}

.trait-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(158px, 1fr));
  gap: 8px 18px;
}

.trait {
  display: flex;
  align-items: center;
  gap: 10px;
}

.trait-name {
  flex: none;
  width: 32px;
  font-size: 12.5px;
  color: var(--c-text-body);
}

.trait-range {
  flex: 1;
  min-width: 0;
  height: 4px;
  appearance: none;
  border-radius: 999px;
  background: var(--c-border-strong);
  outline: none;
  cursor: pointer;
}

.trait-range::-webkit-slider-thumb {
  appearance: none;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--c-accent);
  border: 2px solid var(--c-surface);
  box-shadow: var(--shadow-hair);
}

.trait-range::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--c-accent);
  border: 2px solid var(--c-surface);
}

.trait-value {
  flex: none;
  min-width: 28px;
  text-align: right;
  font-size: 13px;
  font-weight: 500;
  color: var(--c-text);
  font-variant-numeric: tabular-nums;
}

.random {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 20px;
  border: 1px dashed var(--c-border-strong);
  border-radius: var(--r-sm);
  background: var(--c-surface-sunken);
  color: var(--c-text-body);
  font-size: 13.5px;
  cursor: pointer;
}

.random:hover {
  border-color: var(--c-accent);
  background: var(--c-accent-soft);
  color: var(--c-accent-hover);
}

.opening-foot {
  display: flex;
  flex-direction: column;
  gap: 9px;
  padding: 0 16px 16px;
}

.begin {
  padding: 11px 0;
  border: none;
  border-radius: var(--r-sm);
  background: var(--c-accent);
  color: #ffffff;
  font-size: 13.5px;
  font-weight: 500;
  cursor: pointer;
}

.begin:not(:disabled):hover {
  background: var(--c-accent-hover);
}

.begin:disabled {
  background: var(--c-border-strong);
  color: var(--c-bg-alt);
  cursor: default;
}

.opening-hint {
  min-height: 16px;
  text-align: center;
  font-size: 12px;
  color: var(--c-accent-hover);
}

.opening-hint.is-quiet {
  color: var(--c-text-faint);
}
