
.skills {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 14px 16px 16px;
}

.group {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.group-label {
  font-size: 12px;
  color: var(--c-text-faint);
}

.row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.skill {
  display: inline-flex;
  align-items: baseline;
  gap: 7px;
  padding: 5px 11px;
  border: 1px solid var(--c-border);
  border-radius: 999px;
  background: var(--c-surface-sunken);
  font-size: 12.5px;
}

.skill:hover {
  border-color: var(--c-accent-line);
  background: var(--c-accent-soft);
}

.skill-name {
  color: var(--c-text);
}

.skill-level {
  font-size: 12px;
  font-weight: 600;
  color: var(--c-accent-hover);
  font-variant-numeric: tabular-nums;
}

.skill-pct {
  font-size: 11.5px;
  color: var(--c-text-muted);
  font-variant-numeric: tabular-nums;
}

.skill-cap {
  font-size: 11px;
  color: var(--c-text-faint);
}

.empty {
  font-size: 12.5px;
  color: var(--c-text-faint);
}
