
.meter {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.meter-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.meter-label {
  font-size: 13px;
  color: var(--c-text-body);
}

.meter-value {
  font-size: 13px;
  font-weight: 500;
  color: var(--c-text);
  font-variant-numeric: tabular-nums;
}

.meter-max {
  margin-left: 1px;
  font-size: 11px;
  font-weight: 400;
  color: var(--c-text-faint);
}

.meter-track {
  height: 4px;
  border-radius: 999px;
  background: var(--c-border);
  overflow: hidden;
}

.meter-fill {
  height: 100%;
  border-radius: 999px;
  transition: width 0.4s var(--ease-out), background-color 0.2s var(--ease);
}
