
.archive {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 14px 16px 16px;
}

.archive-meters {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 12px 18px;
}

.group {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.group-label {
  font-size: 12px;
  color: var(--c-text-faint);
}

.row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.tag {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  padding: 4px 11px;
  border: 1px solid var(--c-border);
  border-radius: 999px;
  background: var(--c-surface-sunken);
  font-size: 12.5px;
  color: var(--c-text-body);
}

.tag.is-accent {
  border-color: var(--c-accent-line);
  background: var(--c-accent-soft);
}

.tag em {
  font-style: normal;
  font-size: 11px;
  color: var(--c-text-faint);
}

.tag b {
  font-weight: 600;
  color: var(--c-accent-hover);
  font-variant-numeric: tabular-nums;
}

.tag b.is-neg {
  color: var(--c-alarm);
}

.empty {
  font-size: 12.5px;
  color: var(--c-text-faint);
}

.assets {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.asset-tag {
  margin-top: 4px;
  font-size: 11.5px;
  color: var(--c-text-faint);
}

.asset-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-size: 12.5px;
}

.asset-row b {
  flex: none;
  font-weight: 500;
  color: var(--c-text);
}

.asset-row span {
  color: var(--c-text-body);
}

.asset-row em {
  font-style: normal;
  font-size: 11.5px;
  color: var(--c-text-faint);
}
