
.finale {
  display: flex;
  flex-direction: column;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: var(--r-md);
  overflow: hidden;
  animation: cl-enter 0.5s var(--ease-out) both;
}

.finale-head {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  padding: 30px 20px 26px;
  background: var(--c-bg-alt);
  border-bottom: 1px solid var(--c-border);
}

.finale-kicker {
  font-size: 12px;
  letter-spacing: 0.16em;
  color: var(--c-text-muted);
}

.finale-age {
  font-size: 38px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.03em;
  color: var(--c-text);
  font-variant-numeric: tabular-nums;
}

.finale-age-unit {
  margin-left: 5px;
  font-size: 15px;
  font-weight: 400;
  color: var(--c-text-muted);
}

.finale-cause {
  font-size: 13px;
  color: var(--c-text-muted);
}

.finale-block {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 18px 20px;
  border-bottom: 1px solid var(--c-border);
}

.finale-label {
  font-size: 12px;
  color: var(--c-text-faint);
}

.finale-text {
  font-family: var(--f-serif);
  font-size: 14px;
  line-height: 1.85;
  color: var(--c-text-body);
  white-space: pre-wrap;
}

.finale-foot {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 24px 20px 26px;
}

.finale-epitaph {
  font-family: var(--f-serif);
  font-size: 16px;
  line-height: 1.7;
  text-align: center;
  color: var(--c-text);
}

.finale-rate {
  font-size: 12px;
  letter-spacing: 0.2em;
  color: var(--c-text-faint);
}
